///
/// \brief Compute the permutation of linear grid indices effected by 'trans'.
///
/// Assumes that all transformed points are contained in the grid.
///
void compute_cartesian_grid_3d_permutation(const struct cartesian_grid_3d* grid, const struct imat3x3* trans, glong* perm)
{
	const glong num_points = cartesian_grid_3d_num_points(grid);

	for (glong idx = 0; idx < num_points; ++idx)
	{
		union cartesian_grid_point_3d pt;
		linear_index_to_cartesian_grid_point_3d(grid, idx, &pt);

		union cartesian_grid_point_3d transformed_pt;
		transform_cartesian_grid_point_3d(trans, &pt, &transformed_pt);

		perm[idx] = cartesian_grid_point_3d_to_linear_index(grid, &transformed_pt);
	}
}
